import { Link } from "react-router-dom";
import React, { useEffect, useState } from "react";
import PropTypes from "prop-types";
import { getAllAgences, deleteAgenceById } from "../../services/ApiAgence";

// components
export default function CardAgence({ color }) {
  const [Agences, setAgences] = useState([]);

  const getAgence = async () => {
    try {
      const res = await getAllAgences();
      // Filtrer les agences pour supprimer celles avec des champs vides
      const filteredAgences = res.data.filter(
        (agence) =>
          agence.Nom &&
          agence.Code &&
          agence.ville &&
          agence.local &&
          agence.codePostal
      );
      setAgences(filteredAgences);
    } catch (error) {
      console.log(error);
    }
  };

  const deleteAgence = async (id) => {
    try {
      await deleteAgenceById(id);
      getAgence(); // Rafraîchir la liste des agences après suppression
    } catch (error) {
      console.log(error);
    }
  };

  useEffect(() => {
    getAgence();
  }, []);

  return (
    <>
      <div
        className={
          "relative flex flex-col min-w-0 break-words w-full mb-6 shadow-lg rounded " +
          (color === "light" ? "bg-white" : "bg-lightBlue-900 text-white")
        }
      >
        <div className="rounded-t mb-0 px-4 py-3 border-0">
          <div className="flex flex-wrap items-center">
            <div className="relative w-full px-4 max-w-full flex-grow flex-1">
              <h3
                className={
                  "font-semibold text-lg " +
                  (color === "light" ? "text-blueGray-700" : "text-white")
                }
              >
                Liste des Agences
              </h3>
            </div>
            {/* Add button */}
            <div className="w-full text-right">
              <Link to="/admin/AddAgence">
                <button className="bg-blue-500 hover:bg-blue-700 text-white font-semibold text-sm px-6 py-2 rounded-full shadow-md">
                  + Ajouter Agence
                </button>
              </Link>
            </div>
          </div>
        </div>
        <div className="block w-full overflow-x-auto">
          <table className="items-center w-full bg-transparent border-collapse">
            <thead>
              <tr>
                {["Nom", "Code", "Ville", "Local", "Code Postal", "Actions"].map((title, i) => (
                  <th
                    key={i}
                    className={
                      "px-6 align-middle border border-solid py-3 text-xs uppercase border-l-0 border-r-0 whitespace-nowrap font-semibold text-left " +
                      (color === "light"
                        ? "bg-blueGray-50 text-blueGray-500 border-blueGray-100"
                        : "bg-lightBlue-800 text-lightBlue-300 border-lightBlue-700")
                    }
                  >
                    {title}
                  </th>
                ))}
              </tr>
            </thead>
            <tbody>
              {Agences.length > 0 ? (
                Agences.map((agence, index) => (
                  <tr key={index}>
                    <th className="border-t-0 px-6 align-middle border-l-0 border-r-0 text-xs whitespace-nowrap p-4 text-left flex items-center">
                      <span
                        className={
                          "ml-3 font-bold " +
                          (color === "light" ? "text-blueGray-600" : "text-white")
                        }
                      >
                        {agence.Nom}
                      </span>
                    </th>
                    <td className="border-t-0 px-6 align-middle border-l-0 border-r-0 text-xs whitespace-nowrap p-4">
                      {agence.Code}
                    </td>
                    <td className="border-t-0 px-6 align-middle border-l-0 border-r-0 text-xs whitespace-nowrap p-4">
                      {agence.ville}
                    </td>
                    <td className="border-t-0 px-6 align-middle border-l-0 border-r-0 text-xs whitespace-nowrap p-4">
                      {agence.local}
                    </td>
                    <td className="border-t-0 px-6 align-middle border-l-0 border-r-0 text-xs whitespace-nowrap p-4">
                      {agence.codePostal}
                    </td>
                    <td className="border-t-0 px-6 align-middle border-l-0 border-r-0 text-xs whitespace-nowrap p-4 text-center">
                      <div className="flex gap-3 justify-center">
                        {/* Modifier Button */}
                        <Link to={`/admin/update-agence/${agence._id}`}>
                          <button className="bg-green-500 hover:bg-green-700 text-white font-semibold text-sm px-4 py-2 rounded-full shadow-md transition duration-300 transform hover:scale-105">
                            ✏️ Modifier
                          </button>
                        </Link>
                        {/* Ajouter Admin Button */}
                        <Link to={`/admin/add-admin/${agence._id}`}>
                          <button className="bg-yellow-500 hover:bg-yellow-700 text-white font-semibold text-sm px-4 py-2 rounded-full shadow-md transition duration-300 transform hover:scale-105">
                            🔑 Ajouter Admin
                          </button>
                        </Link>
                        {/* Supprimer Button */}
                        <button
                          className="bg-red-500 hover:bg-red-700 text-white font-semibold text-sm px-4 py-2 rounded-full shadow-md transition duration-300 transform hover:scale-105"
                          onClick={() => deleteAgence(agence._id)}
                        >
                          🗑️ Supprimer
                        </button>
                      </div>
                    </td>
                  </tr>
                ))
              ) : (
                <tr>
                  <td colSpan="6" className="text-center py-4 text-red-500">
                    Aucune agence disponible.
                  </td>
                </tr>
              )}
            </tbody>
          </table>
        </div>
      </div>
    </>
  );
}

CardAgence.defaultProps = {
  color: "light",
};

CardAgence.propTypes = {
  color: PropTypes.oneOf(["light", "dark"]),
};
